#!/usr/bin/env python3
"""Agentic Compass - AI Agent Self-Reflection Tool"""

import argparse
import re
from pathlib import Path

def parse_args():
    parser = argparse.ArgumentParser(description='Agentic Compass Tool')
    parser.add_argument('--daily', default='memory/2026-01-31.md', help='Daily memory file')
    parser.add_argument('--long', default='MEMORY.md', help='Long-term memory file')
    parser.add_argument('--write', action='store_true', help='Write plan to memory/agentic-compass.md')
    return parser.parse_args()

def load_file(path):
    try:
        return Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return ''

def load_errors(path='logs/tool-errors.log'):
    try:
        return Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return ''

def score_completion_rate(daily_content):
    """Count [DONE] markers in memory files"""
    done_count = len(re.findall(r'\[DONE\]', daily_content))
    task_count = len(re.findall(r'^[-*]\s+', daily_content, re.MULTILINE))
    if task_count == 0:
        return 0.5, "50% - no tasks found"
    rate = done_count / task_count
    return rate, f"{done_count}/{task_count} tasks completed"

def score_response_relevance(daily_content):
    """Check for user confirmations/corrections"""
    confirmations = len(re.findall(r'(confirmed|correct|right|thanks)', daily_content, re.IGNORECASE))
    corrections = len(re.findall(r'(wrong|incorrect|actually|should have)', daily_content, re.IGNORECASE))
    if corrections == 0:
        return 0.8, "80% - no corrections needed"
    return max(0.2, 0.8 - corrections * 0.2), f"{corrections} corrections needed"

def score_tool_usage(error_content):
    """Parse tool error logs"""
    error_count = len(error_content.strip().split('\n')) if error_content.strip() else 0
    if error_count == 0:
        return 1.0, "100% - no errors"
    return max(0.2, 1.0 - error_count * 0.2), f"{error_count} tool errors"

def score_memory_consistency(daily_content, long_content):
    """Check if prior decisions are referenced/forgotten"""
    # Check for "forgot" mentions
    forgot_count = len(re.findall(r'\bforgot\b', daily_content, re.IGNORECASE))
    return max(0.3, 1.0 - forgot_count * 0.3), f"{forgot_count} forgotten items"

def score_initiative(daily_content):
    """Count proactive actions"""
    proactive_patterns = [
        r'proposed.*without being asked',
        r'proactive',
        r'started.*without',
        r'suggested',
        r'initiated'
    ]
    count = sum(len(re.findall(p, daily_content, re.IGNORECASE)) for p in proactive_patterns)
    if count == 0:
        return 0.4, "40% - no proactive actions"
    return min(1.0, 0.4 + count * 0.3), f"{count} proactive actions"

def analyze_and_generate_plan(daily_path, long_path):
    daily = load_file(daily_path)
    long = load_file(long_path)
    errors = load_errors()

    # Calculate scores
    scores = {
        'Completion Rate': score_completion_rate(daily),
        'Response Relevance': score_response_relevance(daily),
        'Tool Usage Quality': score_tool_usage(errors),
        'Memory Consistency': score_memory_consistency(daily, long),
        'Initiative': score_initiative(daily)
    }

    avg_score = sum(s[0] for s in scores.values()) / len(scores)
    weakest = min(scores.items(), key=lambda x: x[1][0])

    # Generate action plan
    plan = f"""# Agent Action Plan

Generated by Agentic Compass

## Score: {avg_score:.1f}/5

### Weakest Axis: {weakest[0]} ({weakest[1][1]})

## Action Items

### Proactive Task (Start Without Prompt)
- Review and fix the cron failures that were proposed earlier

### Deferred/Cron Item
- Schedule weekly review of tool error logs to prevent timeout issues

### Avoidance Rule (Stop Doing X)
- Stop retrying gateway diagnostics without checking network status first

### Concrete Ship Output
- Update skills-to-build prioritization list (was forgotten previously)

## Axis Scores
"""
    for axis, (score, detail) in scores.items():
        plan += f"- **{axis}**: {score:.0%} ({detail})\n"

    return plan

def main():
    args = parse_args()

    plan = analyze_and_generate_plan(args.daily, args.long)

    if args.write:
        output_path = Path('memory/agentic-compass.md')
        output_path.write_text(plan, encoding='utf-8')
        print(f"Plan written to {output_path}")
    else:
        print(plan)

if __name__ == '__main__':
    main()
